    :raises IOError: passed from any file operations that fail.
    """
    try:
        with open(filename, 'r') as file:
            for line in file:
                line = line.strip()
                if line.startswith('#') or not line:
                    continue
                key, value = line.split(':')
                value = value.strip()
                if key.isdigit():
                    key = int(key)
                self.pack[key] = value
    except IOError:
        raise IOError

def read_file(self, filename):
    """
    :raises IOError: passed from any file operations that fail.
    """
    try:
        with open(filename, 'r') as f:
            content = f.readlines()

        for line in content:
            key, generator, modulus = line.strip().split(',')
            key = int(key)
            generator = int(generator)
            modulus = int(modulus)

            if key in self.pack:
                self.pack[key].append((generator, modulus))
            else:
                self.pack[key] = [(generator, modulus)]

    except IOError:
        print(f"Failed to open {filename} for reading.")
        raise

def read_file(self, filename):
    """
    Reads a file and stores its content into the 'pack' attribute.

    :param filename: the name of the file to read.
    :raises IOError: passed from any file operations that fail.
    """
    try:
        with open(filename, 'r') as file:
            content = file.read()
            self.pack = {filename: content}
    except IOError:
        raise IOError("Error occurred while reading file: {}".format(filename))
